package com.zest.products.auth;
import org.springframework.beans.factory.annotation.Value; import org.springframework.security.authentication.*; import org.springframework.security.core.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.time.temporal.ChronoUnit; import java.util.*;
@Service @Transactional public class AuthService { private final AuthenticationManager auth; private final AppUserRepository users; private final RefreshTokenRepository tokens; private final JwtService jwt; private final long days; public record Tokens(String accessToken,String refreshToken,String tokenType){ } public AuthService(AuthenticationManager a,AppUserRepository u,RefreshTokenRepository t,JwtService j,@Value("${app.jwt.refresh-token-days}") long d){auth=a;users=u;tokens=t;jwt=j;days=d;} public Tokens login(String username,String password){auth.authenticate(new UsernamePasswordAuthenticationToken(username,password));return issue(users.findByUsername(username).orElseThrow());} public Tokens refresh(String token){RefreshToken old=tokens.findByToken(token).orElseThrow(()->new BadCredentialsException("Invalid refresh token"));if(old.isRevoked()||old.getExpiresAt().isBefore(Instant.now()))throw new BadCredentialsException("Expired refresh token");old.setRevoked(true);return issue(old.getUser());} private Tokens issue(AppUser u){RefreshToken r=new RefreshToken();r.setUser(u);r.setToken(UUID.randomUUID().toString());r.setExpiresAt(Instant.now().plus(days,ChronoUnit.DAYS));tokens.save(r);return new Tokens(jwt.create(u),r.getToken(),"Bearer");} }
